-- Phone Hustlers CMS
-- In Supabase: SQL Editor → New query → paste this file → Run.
-- Then open /admin and sign in. This file also loads every site section, including the VICIdial dialer.

create table if not exists public.sections (
  id text primary key,
  label text not null,
  sort integer not null default 0,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.sections enable row level security;

drop policy if exists "Anyone can read sections" on public.sections;
create policy "Anyone can read sections"
  on public.sections
  for select
  using (true);

drop policy if exists "Signed-in users can write sections" on public.sections;
create policy "Signed-in users can write sections"
  on public.sections
  for all
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');

grant select on public.sections to anon, authenticated;
grant insert, update, delete on public.sections to authenticated;

insert into storage.buckets (id, name, public)
values ('media', 'media', true)
on conflict (id) do nothing;

drop policy if exists "Public read media" on storage.objects;
create policy "Public read media"
  on storage.objects
  for select
  using (bucket_id = 'media');

drop policy if exists "Signed-in upload media" on storage.objects;
create policy "Signed-in upload media"
  on storage.objects
  for insert
  with check (bucket_id = 'media' and auth.role() = 'authenticated');

drop policy if exists "Signed-in update media" on storage.objects;
create policy "Signed-in update media"
  on storage.objects
  for update
  using (bucket_id = 'media' and auth.role() = 'authenticated');

drop policy if exists "Signed-in delete media" on storage.objects;
create policy "Signed-in delete media"
  on storage.objects
  for delete
  using (bucket_id = 'media' and auth.role() = 'authenticated');

do $$
begin
  alter publication supabase_realtime add table public.sections;
exception
  when duplicate_object then null;
end $$;

create table if not exists public.inquiries (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text not null,
  email text not null,
  company text default '',
  industry text default '',
  message text default '',
  created_at timestamptz not null default now()
);

alter table public.inquiries enable row level security;

drop policy if exists "Anyone can send an inquiry" on public.inquiries;
create policy "Anyone can send an inquiry"
  on public.inquiries
  for insert
  with check (true);

drop policy if exists "Signed-in users can read inquiries" on public.inquiries;
create policy "Signed-in users can read inquiries"
  on public.inquiries
  for select
  using (auth.role() = 'authenticated');

grant insert on public.inquiries to anon, authenticated;
grant select on public.inquiries to authenticated;

-- Seed every site section, including ones added after the first setup.
-- Safe to run again: existing rows are left as you edited them.

insert into public.sections (id, label, sort, data)
values
  ('meta', 'Site title', 0, '{"title":"Phone Hustlers — Call Center","description":"Phone Hustlers is a call center on VICIdial. Our predictive dialer lets each caller make hundreds of calls in a shift. We explain the offer and book the next step."}'::jsonb),
  ('site', 'Menu, footer, and buttons', 1, '{"cal":"https://cal.com/","email":"inquires@phonehustler.com","emailLabel":"Email Us","phone":"+63 945 620 6543","phoneTel":"+639456206543","inquiryTitle":"Talk to us","inquiryText":"Tell us the offer and the list. We will run it on VICIdial and call you back.","inquiryButton":"Send my details","inquiryThanks":"We got your note. We will call you soon.","navButton":"Book a Call","menuOpen":"Menu","menuClose":"Close","exploreLabel":"Explore","socialsLabel":"Socials","copyright":"©2026 Phone Hustlers.","credit":"Built by Apex Technology","footerBlurb":"We call with VICIdial. It is a predictive dialer, so one caller can reach hundreds of people in a shift.","ctaTitle":"Your list can get hundreds of calls a shift","ctaBody":"We load the names into VICIdial. Callers talk only when someone picks up, then book the next step.","ctaPeople":"Our callers","ctaButton":"Book a Call","nav":[{"label":"Home","to":"/"},{"label":"Industries","to":"/#services"},{"label":"Our Work","to":"/case-studies"},{"label":"About","to":"/about-us"},{"label":"Articles","to":"/blog"}],"footerLinks":[{"label":"Industries","to":"/#services","external":false},{"label":"Our Work","to":"/case-studies","external":false},{"label":"Process","to":"/#steps-cta-section","external":false},{"label":"About","to":"/about-us","external":false},{"label":"Contact Us","to":"https://cal.com/","external":true},{"label":"404","to":"/404","external":false}],"socials":[{"label":"X/Twitter","to":"https://x.com/home"},{"label":"Youtube","to":"https://www.youtube.com/"},{"label":"Instagram","to":"https://www.instagram.com/"},{"label":"Linkedin","to":"https://www.linkedin.com"}]}'::jsonb),
  ('hero', 'Home banner', 2, '{"before":"Our ","accent":"Dialer","after":" Makes Hundreds of Calls","sub":"It is called VICIdial. It calls multiple numbers at once. A caller talks only when someone picks up.","button":"Book a Call","banner":"/hero.jpg?v=2","bannerAlt":"A Phone Hustlers specialist on a headset, lit against a dark office","name":"Jay Benz","role":"CEO at Phone Hustlers","talk":"Talk to us","image":"/jay-benz.jpg"}'::jsonb),
  ('aboutHome', 'Home about strip', 3, '{"tag":"About Us","trusted":"Trusted by the companies we call for","stars":"★★★★★","headline":"One caller used to wait through every ring. VICIdial does the waiting now.","fade":"Hundreds of calls in one shift.","button":"Read More","buttonTo":"/about-us","videoImage":"https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=1400&q=80","quote":"In a few weeks, people who wanted help started booking time with us. The calls were easy to follow.","quoteName":"Alice Miller","quoteRole":"Owner, solar company","quoteImage":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=120&q=80","logos":["Solar","Medicare","Auto Insurance","Business Loans","Final Expense","Medical Alert","Security"],"faces":["/jay-benz.jpg","https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80","https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=200&q=80","https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=200&q=80"],"stats":[{"label":"Calling teams trained","value":1500,"suffix":"+","prefix":""},{"label":"More appointments booked","value":87,"suffix":"%","prefix":""},{"label":"Sales our callers helped","value":30,"suffix":"M+","prefix":"$"},{"label":"Calls handled","value":4.2,"suffix":"M","prefix":""}]}'::jsonb),
  ('dialer', 'VICIdial dialer', 4, '{"tag":"The Dialer","title":"It calls multiple numbers at once","fade":"The caller only hears a hello","body":"A normal phone calls one number and waits. VICIdial calls multiple numbers at the same time. Rings and busy tones stay on the computer. A caller joins only when a real person picks up. That is how one person can make hundreds of calls in a shift.","button":"Put my list on VICIdial","oldLabel":"The old way","oldTitle":"One number at a time","oldPoints":["Calls one number, then waits","Busy tones and voicemail eat the shift","Only a few dozen real talks"],"kicker":"Predictive dialer","name":"VICIdial","pitch":"Multiple numbers ring together. The first hello goes straight to a caller.","stat":"Hundreds","statLabel":"of calls from one caller, in one shift","lines":["Number 1","Number 2","Number 3","Number 4","Number 5"],"ringLabel":"Dialing","liveLabel":"Picked up","points":["Multiple numbers at once","You bring the list","Reps stay in live talks"],"steps":[{"title":"Load the list","body":"We put the names into VICIdial. You do not buy a dialer."},{"title":"Call them together","body":"It calls multiple numbers at once. Empty lines stay on the computer, not on the caller."},{"title":"Talk and book","body":"The rep explains the offer and sets the next step."}]}'::jsonb),
  ('solution', 'How we help', 5, '{"tag":"Our Solution","title":"The Dialer That Keeps","fade":"Every Caller Talking","chart":"More live answers","photo":"https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1600&q=80","items":[{"title":"VICIdial dials for us","body":"It is a predictive dialer. It calls multiple numbers at once. A caller joins only when a real person picks up.","icon":"page"},{"title":"Hundreds of calls a shift","body":"One rep is not stuck listening to rings. They spend the shift talking, so one person can reach hundreds of people.","icon":"layers"},{"title":"We book the next step","body":"A good call ends with a time on the calendar, a clear no, or a note about what the person still needs.","icon":"route"}]}'::jsonb),
  ('workHome', 'Home work heading', 6, '{"tag":"Stories","title":"Our Work","range":"Calls we made in 2025–26","button":"See Our Work","buttonTo":"/case-studies","side":"Real phone work on VICIdial, for the industries we serve."}'::jsonb),
  ('cases', 'Our work stories', 7, '{"pageTitle":"Real calls.","pageIntro":"Stories from the industries we serve. Each one is a calling job, told in plain words.","missing":"Story not found","back":"Back to our work","industryLabel":"Industry","overviewLabel":"Overview","problemLabel":"The problem","didLabel":"What we did","moreTitle":"More of our work","moreBody":"Other calls we made.","items":[{"slug":"kroma","name":"Kroma","date":"2026-03-19T00:00:00.000Z","category":"Final Expense","image":"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1400&q=80","teaser":"Called families about final expense insurance and booked more times to talk.","overview":"Kroma helps families look at small life insurance plans for final expenses.","industry":"Final Expense Insurance","challengeIntro":"People asked for information, then nobody called them back.","challenge":"Forms came in every day. By the time someone called, the family had moved on or forgotten why they asked. The few calls that did happen used long, confusing words.","strategyIntro":"We called the same day, in plain words.","strategy":"We wrote a short script, trained a small team, and called new requests the day they came in. Callers explained the plan in one sentence and offered a time to talk with a licensed person.","results":[{"label":"more appointments","value":"3.4x"},{"label":"fewer missed calls","value":"42%"},{"label":"people who stayed on the line","value":"5.1 in 10"}]},{"slug":"powersurge","name":"PowerSurge","date":"2025-06-04T00:00:00.000Z","category":"Solar","image":"https://images.unsplash.com/photo-1444012830796-83db7e1db0d3?auto=format&fit=crop&w=1400&q=80","teaser":"Called homeowners about solar and booked more visits to the house.","overview":"PowerSurge puts solar on homes and needed people to show up for a visit.","industry":"Solar","challengeIntro":"Homeowners raised a hand, then went quiet.","challenge":"The company had names of people who wanted a solar quote. Those people did not answer a long email. They needed a short phone call that explained the visit.","strategyIntro":"We called and booked a time at the house.","strategy":"Callers said who they were, explained that a visit is free and takes about an hour, and offered two times. If someone said no, we wrote it down and did not keep pushing.","results":[{"label":"more booked visits","value":"4.2x"},{"label":"jobs from those visits","value":"$1.1M"},{"label":"more people who showed up","value":"38%"}]},{"slug":"asterisk","name":"Asterisk","date":"2025-05-04T00:00:00.000Z","category":"Medicare","image":"https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1400&q=80","teaser":"Called people with Medicare questions and set more times with an agent.","overview":"Asterisk helps people compare Medicare supplement plans.","industry":"Medicare Supplement","challengeIntro":"Older adults had questions and no one to ask.","challenge":"People wanted a simple answer about their plan. The old calls were fast and full of plan codes. Many folks hung up before they understood the offer.","strategyIntro":"We slowed the call down and used everyday words.","strategy":"The script avoided plan codes. Callers asked what the person already had, explained the next conversation in one sentence, and booked a time with a licensed agent.","results":[{"label":"more good appointments","value":"3x"},{"label":"more people who showed up","value":"47%"},{"label":"more plans started","value":"2.5x"}]},{"slug":"grotesks","name":"Grotesks","date":"2026-03-26T00:00:00.000Z","category":"Business Loans","image":"https://images.unsplash.com/photo-1523398002811-999ca8dec234?auto=format&fit=crop&w=1400&q=80","teaser":"Called shop owners the same day and helped more of them finish a loan request.","overview":"Grotesks finds business loans for shop owners.","industry":"Business Loans","challengeIntro":"Owners filled out a form and never heard back.","challenge":"By the next day, many owners had called a different company. The ones who were reached got a speech they could not follow.","strategyIntro":"We called the same day and walked through one next step.","strategy":"Callers confirmed the business, explained that the next step was a short application, and stayed on the line while the owner started it. If they were busy, we booked a better time.","results":[{"label":"more finished applications","value":"3.8x"},{"label":"more yes answers","value":"52%"},{"label":"shorter calls","value":"24%"}]}]}'::jsonb),
  ('why', 'Why us', 8, '{"tag":"Why Choose Us","title":"Why companies choose our dialer","body":"VICIdial keeps every caller in a live talk. Empty rings do not eat the shift.","button":"Book a Call","cardTitle":"Hundreds of calls","cardBody":"Each rep can reach hundreds of people in one shift. The dialer does the waiting.","chipA":"VICIdial","chipB":"Live answers","photoLeft":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=800&q=80","photoRight":"https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=1000&q=80","rowA":["VICIdial","Live answers","Hundreds a shift"],"rowB":["No empty rings","Kind callers","More bookings"],"highlightA":"VICIdial","highlightB":"No empty rings","rightTitle":"Talk time, not wait time","rightBody":"The computer dials. The caller starts when a real person says hello."}'::jsonb),
  ('industries', 'Industries we serve', 9, '{"title":"Industries We Serve","items":["Merchant Cash Advance","Business Loans","Health Insurance","Life Insurance","Final Expense Insurance","Auto Insurance","Medical Alert","Reverse Mortgage","Travel/Vacation","Solar","Tax Settlement","Medicare Supplement","Home/Business Security","Pain Relief","Addiction Treatment","Walk In Tubs"]}'::jsonb),
  ('process', 'How we work', 10, '{"tag":"Process","title":"How the dialer job works","body":"Five simple steps. VICIdial does the ringing.","steps":[{"title":"Learn the offer","body":"We learn what you sell, who it is for, and what a good call sounds like."},{"title":"Write the words","body":"We write a short script. Greeting, one clear offer, two questions, and a way to book a time."},{"title":"Train the callers","body":"The team practices until the call feels natural. If they stumble, we fix the words."},{"title":"Make the calls","body":"We load your list into VICIdial. The dialer rings the numbers. A caller starts talking when a person picks up."},{"title":"Show the results","body":"Each week you see who answered, who booked, and who said no."}],"closeTitle":"Ready for more appointments?","closeButton":"Get Started","rating":"4.9/5","clients":"100+ companies we call for"}'::jsonb),
  ('testimonials', 'What companies say', 11, '{"tag":"Testimonials","title":"What companies say about us","items":[{"quote":"Our booked visits more than doubled. People finally understood the solar offer because someone explained it out loud.","name":"James Walker","role":"Owner, solar company","image":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=80","video":false},{"quote":"","name":"David Clarke","role":"Owner, Aone Insurance","image":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=1000&q=80","video":true},{"quote":"Within a few weeks we had a steady list of people ready to talk about a loan. The calls were clear and never pushy.","name":"Michael Turner","role":"Owner, business loans","image":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=900&q=80","video":false}]}'::jsonb),
  ('pricing', 'Pricing', 12, '{"tag":"Pricing","title":"Simple, affordable plans","fade":"made for every business","plan":"Calling Team","body":"A trained group on VICIdial, calling for your business every day.","price":"$6,000","period":"/Monthly","button":"Book a Call","includes":"Includes","features":["VICIdial on every shift","Hundreds of calls from each caller","A team that learns your offer","A short script in plain words","Notes after each call","Appointments put on your calendar","A simple weekly report"]}'::jsonb),
  ('faq', 'Questions', 13, '{"tag":"FAQ","title":"Questions people ask first","items":[{"q":"What is VICIdial?","a":"It is our predictive dialer. It calls multiple numbers at once and puts a caller on the line only when someone answers."},{"q":"How many calls can one person make?","a":"Hundreds in one shift. They are talking to people, not waiting through rings and busy signals."},{"q":"Do you only make phone calls?","a":"Yes. Phone Hustlers is a call center. VICIdial dials. We talk, we listen, and we book the next step."},{"q":"Who do you call for?","a":"Companies in the industries on this site, like insurance, loans, solar, medical alert, and home services."},{"q":"Do I need my own dialer or my own callers?","a":"No. We bring VICIdial and the callers. You tell us the offer and give us the list."},{"q":"What happens on a call?","a":"We say who we are, explain the offer in one or two sentences, answer questions, and ask if they want a time to talk more."}]}'::jsonb),
  ('teamHome', 'Home team', 14, '{"tag":"Team","title":"The team on the phones","items":[{"name":"Jay Benz","role":"Founder & CEO","image":"/jay-benz.jpg"},{"name":"Team member","role":"Job title","image":""},{"name":"Team member","role":"Job title","image":""},{"name":"Team member","role":"Job title","image":""},{"name":"Team member","role":"Job title","image":""},{"name":"Team member","role":"Job title","image":""}]}'::jsonb),
  ('articles', 'Articles', 15, '{"pageTitle":"Simple notes on VICIdial and better calls","pageIntro":"Short lessons from the dialer and the calls we make every day.","missing":"Article not found","back":"Back to articles","items":[{"slug":"what-a-predictive-dialer-does","title":"What VICIdial Does","date":"2026-03-02T23:00:00.000Z","image":"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=1200&q=80","alt":"A team on headsets","body":"A normal phone wastes the shift. The caller waits through rings, busy signals, and voicemail.\n\nVICIdial is a predictive dialer. It calls many numbers at the same time.\n\nA caller only hears a voice when a real person picks up.\n\nThat is why one rep can make hundreds of calls in a single shift.\n\nMore talk time means more people hear the offer, and more of them book the next step."},{"slug":"why-people-hang-up","title":"Why People Hang Up","date":"2026-02-11T23:00:00.000Z","image":"https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=1200&q=80","alt":"Green Fern","body":"People hang up when the first sentence is confusing.\n\nSay three things, then stop talking:\n\nWho you are\n\nWhy you called\n\nWhat happens next\n\nIf the caller has to think too hard, the person on the other end will hang up.\n\nThis is true for insurance, loans, solar, and every other industry we call for."},{"slug":"a-script-anyone-can-follow","title":"A Script Anyone Can Follow","date":"2026-02-04T23:00:00.000Z","image":"https://images.unsplash.com/photo-1490750967868-88aa4486c946?auto=format&fit=crop&w=1200&q=80","alt":"Yellow Flower","body":"A good script is short.\n\nIt has four parts:\n\nA greeting\n\nThe offer in one sentence\n\nTwo easy questions\n\nA way to book a time\n\nWe write a different script for each industry. A Medicare call should not sound like a walk-in tub call.\n\nIf a line feels stiff, we change it until a caller can say it out loud without reading."},{"slug":"call-the-right-people","title":"Call the Right People","date":"2026-01-07T23:00:00.000Z","image":"https://images.unsplash.com/photo-1501004318641-b39e6451bec6?auto=format&fit=crop&w=1200&q=80","alt":"Orange Flower","body":"A long call list is not a good call list.\n\nWe only call people who might want the offer.\n\nA homeowner might want solar. A shop owner might want a business loan. A grandparent might want a medical alert.\n\nCalling the wrong person wastes their time and yours.\n\nBefore the first dial, we agree on who belongs on the list."},{"slug":"what-a-good-call-sounds-like","title":"What a Good Call Sounds Like","date":"2025-12-28T23:00:00.000Z","image":"https://images.unsplash.com/photo-1468327768560-75b778cbb551?auto=format&fit=crop&w=1200&q=80","alt":"Purple Flower","body":"A good call is calm.\n\nSlow voice. Short sentences. No pushy words.\n\nAnswer the question they asked. Then ask if they want a time on the calendar.\n\nA clear no is a good result. It means we did not waste the next appointment.\n\nA booked time is a better result. That is the job."},{"slug":"tell-the-company-the-truth","title":"Tell the Company the Truth","date":"2025-12-16T23:00:00.000Z","image":"https://images.unsplash.com/photo-1496062031456-07b8f162a322?auto=format&fit=crop&w=1200&q=80","alt":"Lilac Flower","body":"Every week we share three numbers.\n\nHow many people answered.\n\nHow many booked a time.\n\nHow many said no.\n\nWe do not hide the nos. They show us which sentence to fix.\n\nSimple numbers help you decide what to do next."}]}'::jsonb),
  ('aboutPage', 'About page', 16, '{"title":"About us.","intro":"Phone Hustlers is a call center. We use VICIdial, a predictive dialer, so each caller can make hundreds of calls in one shift.","button":"Book a Call","storyTag":"Our Story","story":"We started because people asked for help and nobody called them back. One phone at a time was too slow. VICIdial rings many numbers at once, and a caller talks only when a person picks up.","missionTag":"Our Mission","missionTitle":"Our Mission","mission":"Put your list on a predictive dialer. Every live answer should end with a booked time, a clear no, or a simple note.","teamTag":"Team","teamTitle":"The team on the phones","teamBody":"The people who write the scripts, make the calls, and tell you what happened.","team":[{"name":"Jay Benz","role":"Founder & CEO","image":"/jay-benz.jpg"},{"name":"Sofia Bennett","role":"Head of the Calling Team","image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80"},{"name":"Marcus Ellery","role":"Script Writer","image":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=800&q=80"},{"name":"Elena Cross","role":"Call Quality Lead","image":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=800&q=80"},{"name":"Isabella Reed","role":"Client Care","image":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=800&q=80"},{"name":"Camila Torres","role":"Office Manager","image":"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=800&q=80"}]}'::jsonb),
  ('notFound', 'Missing page', 17, '{"code":"404","message":"This page is not here. Let’s go back home.","button":"Back to Home"}'::jsonb)
on conflict (id) do nothing;
